81	   * caller is responsible for setting the desired CUDA device prior to this
82	   * call if a specific device is already set.
83	   * <p>NOTE: All cudf methods will set the chosen CUDA device in the CUDA
84	   * context of the calling thread after this returns.
85	   * @param allocationMode Allocation strategy to use. Bit set using
86	   *                       {@link RmmAllocationMode#CUDA_DEFAULT},
87	   *                       {@link RmmAllocationMode#POOL} and
88	   *                       {@link RmmAllocationMode#CUDA_MANAGED_MEMORY}
89	   * @param enableLogging  Enable logging memory manager events
90	   * @param poolSize       The initial pool size in bytes
91	   * @throws IllegalStateException if RMM has already been initialized
92	   */
93	  public static void initialize(int allocationMode, boolean enableLogging, long poolSize)
94	      throws RmmException {
95	    LogConf lc = null;
96	    if (enableLogging) {
97	      String f = System.getenv("RMM_LOG_FILE");
98	      if (f != null) {
99	        lc = logTo(new File(f));
100	      } else {
101	        lc = logToStderr();
102	      }
103	    }
104	    initialize(allocationMode, lc, poolSize);
105	  }
